<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $file=basename((string)($_GET['file']??'')); if($file===''||!preg_match('/^mypharmacypos_backup_[0-9_-]+\.sql$/',$file)){http_response_code(400);exit('Invalid backup file.');} $path=dirname(__DIR__).DIRECTORY_SEPARATOR.'backups'.DIRECTORY_SEPARATOR.$file; if(!is_file($path)){http_response_code(404);exit('Backup not found.');} header('Content-Type: application/sql'); header('Content-Disposition: attachment; filename="'.$file.'"'); header('Content-Length: '.filesize($path)); readfile($path); exit;